import itertools,json
jobs='ABCDE'
slot={'A':[10,7,11,4,4],'B':[3,1,1,4,8],'C':[5,4,5,6,2],'D':[3,3,7,1,11],'E':[10,9,10,1,9]}
trans=dict(zip(jobs,[[0,3,3,5,0],[5,0,3,2,0],[5,3,0,2,1],[4,2,4,0,5],[1,5,4,1,0]]))
def nominal(p):
 return sum(slot[j][i] for i,j in enumerate(p))+sum(trans[a][jobs.index(b)] for a,b in zip(p,p[1:]))
def legalcost(p,incident,exchange):
 if p.index('A')>p.index('D'): return None
 pos={j:p.index(j)+1 for j in jobs}
 if incident=='rain':
  if pos['C']==5 or pos['A']==1:return None
  penalty=8*max(0,pos['E']-1)
 elif incident=='road':
  if pos['B']==1 or pos['C']==2:return None
  penalty=5*max(0,pos['D']-3)
 else:
  if pos['D']==5 or pos['B']==5:return None
  penalty=5*max(0,pos['E']-2)
 return nominal(p)+penalty+exchange
records=[]
for p in itertools.permutations(jobs):
 if p.index('A')>p.index('D'):continue
 neighbors=[(p,0)]
 for i in range(5):
  for j in range(i+1,5):
   q=list(p);q[i],q[j]=q[j],q[i];neighbors.append((tuple(q),1))
 repairs={};costs={}
 for incident in ['rain','road','lift']:
  choices=[(c,''.join(q)) for q,e in neighbors if (c:=legalcost(q,incident,e)) is not None]
  if not choices:break
  costs[incident],repairs[incident]=min(choices)
 else:
  records.append({'roster':''.join(p),'score':nominal(p)+max(costs.values()),'repairs':repairs,'repair_costs':costs})
records.sort(key=lambda r:(r['score'],r['roster']))
best=records[0].copy();best['feasible_count']=len(records);best['next_score']=min(r['score'] for r in records if r['score']>best['score'])
print(json.dumps(best))
print('optimal publications',[(r['roster'],r['score']) for r in records if r['score']==best['score']])
print('published nominal',nominal(best['roster']))

