import itertools,json
jobs='ABCDE';published='EABDC'
slot={'A':[10,7,11,4,4],'B':[3,1,1,4,8],'C':[5,4,5,6,2],'D':[3,3,7,1,11],'E':[10,9,10,1,9]}
t=[[0,3,3,5,0],[5,0,3,2,0],[5,3,0,2,1],[4,2,4,0,5],[1,5,4,1,0]]
def distance(p):
 perm=[published.index(x) for x in p];seen=set();cycles=0
 for i in range(5):
  if i not in seen:
   cycles+=1;j=i
   while j not in seen:seen.add(j);j=perm[j]
 return 5-cycles
best={str(i):None for i in range(3)};counts={str(i):0 for i in range(3)};results=[]
for p in itertools.permutations(jobs):
 d=distance(p)
 if d>2 or p.index('A')>p.index('D') or p[4]=='C' or p[0] in 'AE':continue
 nominal=sum(slot[x][i] for i,x in enumerate(p))+sum(t[jobs.index(a)][jobs.index(b)] for a,b in zip(p,p[1:]))
 score=nominal+8*p.index('E')+d+(10 if d==2 else 0)
 k=str(d);counts[k]+=1;best[k]=score if best[k] is None else min(best[k],score)
 results.append((score,''.join(p)))
score,roster=min(results)
print(json.dumps(dict(roster=roster,score=score,best_by_swaps=best,feasible_by_swaps=counts)))
# Independently generate distances by breadth-first exchanges.
dist={published:0};front=[published]
for depth in range(1,3):
 nxt=[]
 for p in front:
  for i in range(5):
   for j in range(i+1,5):
    q=list(p);q[i],q[j]=q[j],q[i];q=''.join(q)
    if q not in dist:dist[q]=depth;nxt.append(q)
 front=nxt
assert all(distance(p)==d for p,d in dist.items())
print('distance validation passed')

